function TRANSCRIPT-DISTRIBUTION(com, open, Q, string_of, W, Rc, Rv):
    counts <- empty map;  total <- |W| * |Rc| * |Rv|
    for each w in W, rho in Rc, r in Rv:
        u  <- string_of(r, w)          # proof(w) for the prover, sim(r,w) for the simulator
        T  <- Q(r)
        tau <- ( com(u, rho), r, u restricted to T, open(u, rho, T) )
        counts[tau] <- counts[tau] + 1
    return { tau : counts[tau] / total }

function IS-PERFECT-HVZK(protocol, sim):
    D_real <- TRANSCRIPT-DISTRIBUTION(..., string_of = (r,p) -> proof(p), W = P, ...)
    D_sim  <- TRANSCRIPT-DISTRIBUTION(..., string_of = sim,               W = S, ...)
    support <- domain(D_real) union domain(D_sim)
    witnesses <- { tau in support : D_real[tau] != D_sim[tau] }
    distance  <- (1/2) * sum over support of | D_real[tau] - D_sim[tau] |
    return ( witnesses is empty, distance, witnesses )

function CERTIFY-SHARP-TRANSITIVITY(G, A, q, constraint):
    targets <- { t in A^q : constraint(t) }
    transitive <- true;  sharply <- true
    for each base in targets:
        mult <- empty map
        for each g in G:
            image <- ( g(base[1]), ..., g(base[q]) )
            mult[image] <- mult[image] + 1
        if some t in targets has mult[t] = 0:
            return ( transitive = false, sharply = false, witness = base, profile = mult )
        if some t in targets has mult[t] != 1:
            sharply <- false;  witness <- base;  profile <- mult
    return ( transitive, sharply, witness, profile )

# sharply = true  =>  |G| = |targets| and the opened view is exactly uniform,
#                     so the bijection criterion certifies perfect simulation
# transitive = false => the opened view retains a G-invariant of the witness

function FIBRE-COUNT(com, open, Rc, u, T, c, o):
    return | { rho in Rc : com(u, rho) = c and open(u, rho, T) = o } |

function PROFILE-HIDING(com, open, Rc, messages, T):
    violations <- empty list
    for each u, v in messages with u = v on T:
        observables <- { (com(u,rho), open(u,rho,T)) } union { (com(v,rho), open(v,rho,T)) }
        for each (c, o) in observables:
            if FIBRE-COUNT(u,T,c,o) != FIBRE-COUNT(v,T,c,o):
                append (u, v, c, o) to violations
    return ( violations is empty, violations )

function CHECK-SIMULATION(Q, proof, sim, P, S, Rv):
    for each r in Rv:
        T <- Q(r)
        N_real <- histogram of  proof(p) restricted to T   over p in P
        N_sim  <- histogram of  sim(r,s) restricted to T   over s in S
        for each view t seen on either side:
            if N_real[t] * |S| != N_sim[t] * |P|:  report mismatch (r, t)
    return ( no mismatches )
